from pathlib import Path
from statistics import median
import hashlib,json,random,subprocess,time,sys
w=Path(sys.argv[1]).resolve();repo=Path.cwd();dest=repo/'experimente/26_native_reparaturansicht'
def digest(data):return hashlib.sha256(data).hexdigest()
def readjson(p):return json.loads(p.read_text())
def run(cmd,cwd):
    p=subprocess.run(cmd,cwd=cwd,capture_output=True)
    if p.returncode: raise RuntimeError([cmd,p.stderr.decode(),p.stdout.decode()[:200]])
    return p.stdout
old=readjson(repo/'experimente/25_blinde_quellreparatur/versuchsplan.json')
archive=readjson(repo/'experimente/25_blinde_quellreparatur/messung.json')
projects={}
for key in ['jury','depot']:
    info=old['families'][key];folder=w/'projects'/key;folder.mkdir(parents=True,exist_ok=True)
    for path,source in info['canonical'].items():
        lang,name=path.split('/')
        if lang!='tide':continue
        for owner,a,b in info['mutations']['tide']:
            if name==owner:
                assert source.count(a)==1;source=source.replace(a,b)
        (folder/name).write_text(source)
    trial=next(r for r in archive['trials'] if r['bug']==key and r['arm']=='G')
    prompt=trial['attempts'][0]['prompt']
    obs=next(l for l in prompt.splitlines() if l.startswith('{"passed":'))
    projects[key]=(folder,'summary.tide','main',obs,prompt)
for key,name,root in [('nano','nano.tide','step'),('invaders','space_invaders.tide','tick')]:
    projects[key]=(repo/'apps',name,root,'Vergleiche die Eingabeverarbeitung.',None)
raw=[];hashes={};cost={}
for i in range(14):
    for j,key in enumerate(projects):
        folder,entry,root,obs,prompt=projects[key]
        rendered=[]
        for variant in (['baseline','batch'] if (i+j)%2==0 else ['batch','baseline']):
            work=w/'timed'/key/variant;work.mkdir(exist_ok=True,parents=True)
            for filename in ('forms','grouped','forms.tsv'):
                (work/filename).unlink(missing_ok=True)
            start=time.monotonic_ns()
            run([w/'control'/variant,work,entry,root,obs,'fragment_view'],folder)
            end=time.monotonic_ns()
            forms=(work/'forms').read_bytes();view=(work/'grouped').read_bytes()
            data=json.loads(view)
            context='\n\n'.join("--- "+f['file']+" ---\n"+f['source'] for f in sorted(data['files'],key=lambda f:f['file']))
            if prompt is not None:assert prompt.endswith(obs+'\n\n'+context) and data['instruction'] in prompt
            evidence=[digest(forms),digest(view),digest(context.encode())]
            hashes.setdefault(key,evidence);assert hashes[key]==evidence
            cost[key]=len(json.loads(forms))
            raw.append(dict(project=key,rep=i-1,method=variant,wall_ns=end-start,stage_s=float((work/'forms-end').read_text())-float((work/'forms-start').read_text())))
            rendered.append([forms,view])
        assert rendered[0]==rendered[1]
    print('block',i,flush=True)
result={}
for k in projects:
    records=[r for r in raw if r['project']==k and r['rep']>0]
    stats={}
    for metric in ['stage_s','wall_ns']:
        vals={v:[r[metric]/(1e9 if metric=='wall_ns' else 1) for r in records if r['method']==v] for v in ['baseline','batch']}
        pairs=list(zip(vals['baseline'],vals['batch']))
        stats[metric]={'reference_s':median(vals['baseline']),'batch_s':median(vals['batch']),'saved_s':median(a-b for a,b in pairs),'factor':median(a/b for a,b in pairs),'wins':sum(a>b for a,b in pairs),'range_saved_s':[min(a-b for a,b in pairs),max(a-b for a,b in pairs)]}
    result[k]=stats
data=dict(raw=raw,medians=result,function_counts=cost,hashes=hashes,build_s=float((w/'build-seconds').read_text()),methods={f:(w/'control'/f).read_text() for f in ['baseline','batch','tide-args']},measure=Path(__file__).read_text())
(dest/'messung.json').write_text(json.dumps(data,indent=2,ensure_ascii=False)+'\n')
print(json.dumps(result))
